].forEach(e=>drop.addEventListener(e,x=>{x.preventDefault();drop.classList.remove('drag')}));drop.ondrop=e=>pick(e.dataTransfer.files[0]);function pick(f){if(!f)return;if(f.type!=='application/pdf'){result.textContent='Please choose a PDF file.';return}selected=f;btn.disabled=false;result.textContent=f.name+' selected.'}btn.onclick=async()=>{if(!selected)return;btn.disabled=true;bar.style.width='0%';result.textContent='Reading PDF…';try{const pdf=await pdfjsLib.getDocument({data:await selected.arrayBuffer()}).promise;for(let i=1;i<=pdf.numPages;i++){const p=await pdf.getPage(i),v=p.getViewport({scale:1.7}),c=document.createElement('canvas');c.width=Math.ceil(v.width);c.height=Math.ceil(v.height);await p.render({canvasContext:c.getContext('2d',{willReadFrequently:true}),viewport:v}).promise;await new Promise(resolve=>c.toBlob(b=>{const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='page-'+i+'.jpg';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);resolve()},'image/jpeg',.9));bar.style.width=Math.round(i/pdf.numPages*100)+'%'}result.textContent=pdf.numPages+' page(s) converted.'}catch(e){console.error(e);result.textContent='Could not convert this PDF. Please try another file.'}finally{btn.disabled=false}};</script><style id="smarttoolz-global-sidebar-css">.smarttoolz-global-sidebar{position:fixed;right:18px;top:88px;width:280px;max-height:calc(100vh - 108px);overflow:auto;z-index:9990;background:#fff;border:1px solid #e5e9f0;border-radius:18px;padding:14px;box-shadow:0 18px 50px rgba(20,30,70,.12)}.st-sidebar-head{display:flex;justify-content:space-between;align-items:center;padding:4px 7px 10px}.st-sidebar-head button{border:0;background:transparent;font-size:24px;cursor:pointer;color:#69758a}.st-sidebar-list a{display:block;padding:9px 10px;margin:2px 0;border-radius:9px;color:#536075;text-decoration:none;font:700 13px/1.25 Inter,system-ui,Arial,sans-serif}.st-sidebar-list a:hover,.st-sidebar-list a.active{background:#f0efff;color:#